import{z as B,x as p,o as E,c as d,q as o,j as s,D as t,d as l,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Glosten 电子限价簿","description":"","frontmatter":{"title":"Glosten 电子限价簿","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/glosten-electronic-lob.md","filePath":"quant/glosten-electronic-lob.md","lastUpdated":1791063341000}'),A={name:"quant/glosten-electronic-lob.md"};function m(u,a,c,h,D,f){const n=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="glosten-电子限价簿" tabindex="-1">Glosten 电子限价簿 <a class="header-anchor" href="#glosten-电子限价簿" aria-label="Permalink to &quot;Glosten 电子限价簿&quot;">​</a></h1><div class="epigraph"><p>若任何人都可以在任意价位提交竞争性限价单，电子公开限价簿可以成为不可避开的交易协议：各档深度由逆向选择决定，价差不必来自垄断专家。</p><footer>—— Glosten, Is the Electronic Open Limit Order Book Inevitable?, Journal of Finance, 1994</footer></div><p><a href="/quant/rosu-dynamic-lob">Roşu</a>用耐心排序生成动态形状。缺口是信息：在竞争性限价供给下，逆向选择如何决定<strong>整条</strong>价格–数量表，而不是一个 \\(\\lambda\\) 或一对 bid/ask。Glosten（1994）问电子公开限价簿是否「不可避免」：当限价单可以自由竞争时，专家的垄断报价能否被压到与簿相同的条件期望价格表。本课不重导单期 Kyle 线性深度，也不重画簿的几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Glosten-Milgrom 的专家报一对单位价格。Kyle 的做市商报一个对总量线性的出清价。电子簿允许交易者在许多价位上留下限价，相当于一条供给曲线：\\(Q\\) 单位市价买，成交均价沿曲线走。若挂单者竞争且风险中性，每一档的价格应等于「吃到这一档」时价值的条件期望，否则有人愿意在更优价位插入。问题是这条竞争性限价曲线是否存在、是否被知情市价单抽干，以及专家能否提供簿给不出的额外保险。</p><p>「不可避免」不是技术预言（世界上仍有批发商与暗池），而是机制比较：在公开、匿名、价格–时间优先的协议里，逆向选择被写进曲线斜率，专家不是逻辑必需。</p><p><span class="marginnote">「逆向选择」翻译成大白话：站在对面的单子里，越急着成交、吃得越深的，越可能是知道内幕的——你接的每一单都是被挑剩下的。「赢者的诅咒」是它的镜像：你挂的限价单成交了，恰恰说明价格事后对你不利，成交本身就是坏消息。</span></p><h3 id="筛与赢者的诅咒" tabindex="-1">筛与赢者的诅咒 <a class="header-anchor" href="#筛与赢者的诅咒" aria-label="Permalink to &quot;筛与赢者的诅咒&quot;">​</a></h3><p>市价单可以选择吃多深。知情者倾向于在价值偏离时吃得更深，于是更差的档位面对更严重的赢者诅咒。竞争性限价必须把更差档的价格设得更不利，曲线向上弯（对买方向）。这与 Kyle 线性是同族现象的非线性版本：边际深度越差，条件期望越极端。单期 \\(\\lambda\\) 是这条曲线在零点的导数近似，本课不把它再解一遍。</p><p><span class="marginnote">Seppi（1997）讨论专家与限价单并存：专家可以提供限价单不提供的剩余供给。Glosten 1994 的基准是纯限价市场。混合市场是边界，不是对「曲线由逆向选择定价」的否定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险中性、竞争性的限价供给者；市价需求来自知情与非知情。公开簿上每一价格 \\(p\\) 处的量，使供给者在被取时盈亏平衡：\\(p=E[V\\mid\\)吃到该档的事件\\(]\\)。知情者选择最优吃量，非知情者因流动性吃随机量。均衡是曲线与吃量策略的固定点。无知情者时曲线平坦在 \\(E[V]\\)，价差可被竞争到栅格最小；有知情者时曲线开口，小单仍可能近乎有效价，大单付出越来越陡的冲击。</p><p>与单位 Glosten-Milgrom 对照：单位模型只有一个 ask，等于「下一笔是买」的期望；电子簿有许多 ask，等于「买到第 \\(k\\) 档」的期望。学习沿深度发生，而不只沿笔数。</p><p><span class="marginnote">数字实例：假设真实价值是 100 元。买第 1 档 100.05 成交 100 股，第 2 档 100.10 再成交 200 股，第 3 档 100.30 再成交 500 股。你的成交均价不是 100.05，而是 \\((100.05\\times100+100.10\\times200+100.30\\times500)/800\\approx100.24\\)——沿曲线走，吃得越深均价越差，这就是「沿供给曲线选点」的含义。</span></p><h3 id="为什么专家可能仍被需要" tabindex="-1">为什么专家可能仍被需要 <a class="header-anchor" href="#为什么专家可能仍被需要" aria-label="Permalink to &quot;为什么专家可能仍被需要&quot;">​</a></h3><p>若限价供给者不能条件于订单规模（只能提前挂好），大单把曲线抽空后，短期内没有人补，瞬时流动性缺口需要愿意事后议价或承担残差的人。Glosten 讨论这种「剩余」需求。电子化之后 HFT 做市用撤单与改价近似连续重新挂曲线，专家的制度角色下降，但残差在压力期仍出现——闪电崩盘课会回到供给撤退。</p>',16)),(E(),s(i,null,{default:t(()=>[r(n,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20Inf%5B%22%E7%9F%A5%E6%83%85%E5%B8%82%E4%BB%B7%E9%80%89%E6%8B%A9%E5%90%83%E5%A4%9A%E6%B7%B1%22%5D%20--%3E%20Curse%5B%22%E6%9B%B4%E5%B7%AE%E6%A1%A3%E8%B5%A2%E8%80%85%E8%AF%85%E5%92%92%E6%9B%B4%E9%87%8D%22%5D%0A%20%20Curse%20--%3E%20Curve%5B%22%E7%AB%9E%E4%BA%89%E6%80%A7%E9%99%90%E4%BB%B7%E6%9B%B2%E7%BA%BF%20p(Q)%22%5D%0A%20%20Liq%5B%22%E9%9D%9E%E7%9F%A5%E6%83%85%E9%9A%8F%E6%9C%BA%E9%87%8F%22%5D%20--%3E%20Curve%0A%20%20Curve%20--%3E%20Inf%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[l("公开限价簿把逆向选择"),e("strong",null,"显示为形状"),l("。厚而平坦的近端意味着小单信息含量低；远离 BBO 迅速变薄意味着大单被当成知情。交易者选择限价还是市价，是在这条曲线上选点：市价沿曲线付冲击，限价则试图成为曲线的一部分、赚价差、担诅咒。Parlour 的排队决定你能否成为曲线上的那一点；Glosten 决定这一点应该标什么价才盈亏平衡。")],-1)),a[5]||(a[5]=e("p",null,"透明度：若曲线可见，非知情大单知道自己会沿曲线走，可能改拆单或走暗池，于是可见曲线面对的流更毒，开口更陡——透明与毒性的反馈，接上一课。",-1)),a[6]||(a[6]=e("p",null,"这条「挂单还是吃单」的决策，回答的是「同一个交易需求为什么会在曲线上选不同的点」：",-1)),(E(),s(i,null,{default:t(()=>[r(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Need%5B%22%E6%9C%89%E4%BA%A4%E6%98%93%E9%9C%80%E6%B1%82%22%5D%20--%3E%20Q1%7B%22%E5%8D%95%E5%AD%90%E5%A4%A7%E5%90%97%22%7D%0A%20%20Q1%20--%20%22%E5%B0%8F%E5%8D%95%22%20--%3E%20Mkt%5B%22%E7%9B%B4%E6%8E%A5%E5%B8%82%E4%BB%B7%E5%90%83%E8%BF%91%E7%AB%AF%22%5D%0A%20%20Q1%20--%20%22%E5%A4%A7%E5%8D%95%22%20--%3E%20Q2%7B%22%E6%80%A5%E5%90%97%22%7D%0A%20%20Q2%20--%20%22%E6%80%A5%22%20--%3E%20Split%5B%22%E6%8B%86%E5%8D%95%E5%88%86%E6%89%B9%E6%B2%BF%E6%9B%B2%E7%BA%BF%E5%90%83%22%5D%0A%20%20Q2%20--%20%22%E4%B8%8D%E6%80%A5%22%20--%3E%20Lim%5B%22%E6%8C%82%E9%99%90%E4%BB%B7%E5%8A%A0%E5%85%A5%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20Lim%20--%3E%20Curse%5B%22%E6%88%90%E4%BA%A4%E4%BA%86%E5%8F%AF%E8%83%BD%E8%A2%AB%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20Lim%20--%3E%20Spread%5B%22%E6%B2%A1%E6%88%90%E4%BA%A4%E8%B5%9A%E4%B8%8D%E5%88%B0%E4%BB%B7%E5%B7%AE%20%E7%99%BD%E6%8E%92%E9%98%9F%22%5D%0A%20%20Split%20--%3E%20Impact%5B%22%E4%BB%98%E5%86%B2%E5%87%BB%20%E5%9D%87%E4%BB%B7%E5%8F%98%E5%B7%AE%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：把限价簿想象成出租车计价器加排队窗——近端（小额）一口价很便宜，远端（大额）每公里加价越来越狠；你可以付高价立刻走（市价单），也可以站进队伍等别人接你的价（限价单），但排队期间价格可能开走，你白等一场。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>竞争、风险中性、无库存，会低估价差、忽略 Ho–Stoll 偏度。离散 tick 使曲线变成阶梯，近端常钉死在一档，斜率不可估。隐藏单使可见曲线不是盈亏平衡曲线。跨市场时「公开簿」不是全部供给。1994 年问的是协议比较，不是预测所有资产都会上电子簿——债券与 FX 的电子化要到本课程最后一单元。</p><p><span class="marginnote">不要把「电子簿不可避免」读成「暗池不应该存在」。Glosten 的条件是公开竞争性限价；一旦大单能逃到不透明场所，曲线的信息集已经改变。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Glosten（1994）把电子公开限价簿写成竞争性限价供给曲线，各档价格是吃到该档时的条件期望。</li><li>知情者选择深度，赢者诅咒使曲线开口；线性 Kyle \\(\\lambda\\) 只是近端近似，本课不重推。</li><li>专家不是逻辑必需，但在限价来不及补给时可提供残差流动性。</li><li>出处：Glosten, <em>Journal of Finance</em>, 1994；单位报价对照 Glosten and Milgrom, 1985；并存见 Seppi, <em>Review of Financial Studies</em>, 1997。</li></ul>',6))])}const _=B(A,[["render",m]]);export{g as __pageData,_ as default};
